class Solution {
public:
    long long popcountDepth(long long n,int k) {
        if(k==0) return 1;
        long long C[61][61]={};
        for(int i=0;i<=60;++i) {
            C[i][0]=C[i][i]=1;
            for(int j=1;j<i;++j) C[i][j]=C[i-1][j-1]+C[i-1][j];
        }
        auto countBits=[&](int ones) {
            long long ans=0;int used=0;
            for(int b=59;b>=0;--b) if((n>>b)&1LL) {
                int need=ones-used;
                if(need>=0 && need<=b) ans+=C[b][need];
                ++used;
            }
            if(used==ones) ++ans;
            return ans;
        };
        long long ans=0;
        for(int ones=1;ones<=50;++ones) {
            int d=0,x=ones;
            while(x!=1) {x=__builtin_popcount((unsigned)x);++d;}
            if(d+1==k) ans+=countBits(ones);
        }
        if(k==1) --ans; // x=1 has depth zero, not one.
        return ans;
    }
};
